// SetFieldExpr assigns the field with the given name a SQL expression, which
// the database evaluates as the UPDATE writes the row. It replaces any value
// the field was set, added, appended or cleared with, as setting it again
// would, and so the column is assigned once.
//
// The field is listed by Fields and Field returns the expression, so a hook
// sees it as it sees any other. What it does not have is a value: a field
// with a validator is refused, since there is nothing for the validator to
// check, and so is one that only a create could write. A create refuses a
// mutation holding an expression at all.
func (m *Mutation) SetFieldExpr(name string, expr sql.Querier) error {
	if expr == nil {
		return fmt.Errorf("no expression for field %s", name)
	}
	if m.op.Is(ent.OpCreate) {
		return fmt.Errorf("field %s cannot be assigned an expression: a create writes values, and an expression is written only by an update", name)
	}
	switch name {
	case FieldMor:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldMorSubscription:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldMorCustomer:
		m.ResetMorCustomer()
	case FieldStatus:
		m.ResetStatus()
	case FieldCurrency:
		m.ResetCurrency()
	case FieldDatePeriodStart:
		m.ResetDatePeriodStart()
	case FieldDatePeriodEnd:
		m.ResetDatePeriodEnd()
	case FieldDateNext:
		m.ResetDateNext()
	case FieldChange:
		m.ResetChange()
	case FieldDateChange:
		m.ResetDateChange()
	case FieldDateCanceled:
		m.ResetDateCanceled()
	case FieldMethodType:
		m.ResetMethodType()
	case FieldMethodBrand:
		m.ResetMethodBrand()
	case FieldMethodLast4:
		m.ResetMethodLast4()
	case FieldLastTransaction:
		m.ResetLastTransaction()
	case FieldLastProgress:
		m.ResetLastProgress()
	case FieldAwaitingPayer:
		m.ResetAwaitingPayer()
	case FieldDateMorUpdated:
		m.ResetDateMorUpdated()
	case FieldDateChecked:
		m.ResetDateChecked()
	case FieldDateUpdated:
		m.ResetDateUpdated()
	case FieldDateErased:
		m.ResetDateErased()
	case FieldDateCreated:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldBillingAccountId:
		return fmt.Errorf("field %s cannot be assigned an expression: it holds an edge, which is set through the edge", name)
	default:
		return fmt.Errorf("unknown Subscription field %s", name)
	}
	if m.exprs == nil {
		m.exprs = make(map[string]sql.Querier)
	}
	m.exprs[name] = expr
	return nil
}

